package com.isc.facebiometricservice.service;

import com.isc.facebiometricservice.api.VerificationRequest;import com.isc.facebiometricservice.api.VerificationResponse;import com.isc.facebiometricservice.api.VerificationStatus;import com.isc.facebiometricservice.biometric.FaceMatcher;import com.isc.facebiometricservice.biometric.ReferenceEmbeddingRepository;import com.isc.facebiometricservice.config.BiometricProperties;import com.isc.facebiometricservice.domain.FaceEmbedding;import org.springframework.stereotype.Service;import java.util.List;

@Service
public class BiometricVerificationService {
 private final ReferenceEmbeddingRepository repository;private final FaceMatcher matcher;private final BiometricProperties properties;
 public BiometricVerificationService(ReferenceEmbeddingRepository repository,FaceMatcher matcher,BiometricProperties properties){this.repository=repository;this.matcher=matcher;this.properties=properties;}
 public VerificationResponse verify(VerificationRequest request){
  if(request==null||request.capture()==null)return invalid(null,null,"EMBEDDING","CAPTURE_REQUIRED","A biometric capture is required.");
  if(!"EMBEDDING".equalsIgnoreCase(request.capture().type()))return invalid(request.requestId(),request.referenceId(),"EMBEDDING","CAPTURE_TYPE_NOT_SUPPORTED","The requested capture type is not supported.");
  if(request.capture().embedding()==null||request.capture().embedding().size()!=properties.dimension())return invalid(request.requestId(),request.referenceId(),"EMBEDDING","EMBEDDING_DIMENSION_MISMATCH","The embedding dimension does not match the configured verification model.");
  float[] values=new float[request.capture().embedding().size()];for(int i=0;i<values.length;i++)values[i]=request.capture().embedding().get(i);boolean normalized=Boolean.TRUE.equals(request.capture().normalized());if(properties.normalizedRequired()&&!normalized)return invalid(request.requestId(),request.referenceId(),"EMBEDDING","NORMALIZED_EMBEDDING_REQUIRED","A normalized embedding is required.");
  var model=request.model();String modelId=model!=null&&model.modelId()!=null?model.modelId():properties.modelId();String modelVersion=model!=null&&model.modelVersion()!=null?model.modelVersion():properties.modelVersion();if(!properties.modelId().equals(modelId)||!properties.modelVersion().equals(modelVersion))return invalid(request.requestId(),request.referenceId(),"EMBEDDING","MODEL_MISMATCH","The supplied embedding was generated by an incompatible biometric model.");
  var reference=repository.find(request.referenceId(),modelId,modelVersion);
  if(reference.isEmpty()){
   var anyReference=repository.findByReferenceId(request.referenceId());
   if(anyReference.isPresent())return outcome(request.requestId(),request.referenceId(),"EMBEDDING",VerificationStatus.INVALID_REQUEST,"MODEL_MISMATCH","The reference exists, but its enrolled biometric model is incompatible with the requested verification model.",null,null,null,null,null,List.of("MODEL_MISMATCH"));
   return outcome(request.requestId(),request.referenceId(),"EMBEDDING",VerificationStatus.INCONCLUSIVE,"REFERENCE_NOT_FOUND","No compatible biometric reference embedding is enrolled for this reference.",null,null,null,null,null,List.of("REFERENCE_NOT_FOUND"));
  }
  FaceEmbedding ref=reference.get();try{double similarity=matcher.similarity(values,ref.values());VerificationStatus result=similarity>=properties.threshold()?VerificationStatus.MATCH:VerificationStatus.NO_MATCH;String code=result==VerificationStatus.MATCH?"MATCH":"SIMILARITY_BELOW_THRESHOLD";String message=result==VerificationStatus.MATCH?"Biometric verification matched the enrolled reference.":"Biometric verification completed, but similarity is below the configured threshold.";return outcome(request.requestId(),request.referenceId(),"EMBEDDING",result,code,message,similarity,properties.threshold(),null,null,null,List.of(code));}catch(IllegalArgumentException ex){return invalid(request.requestId(),request.referenceId(),"EMBEDDING","INVALID_EMBEDDING","The supplied embedding could not be verified.");}
 }
 private VerificationResponse invalid(String requestId,String referenceId,String method,String code,String message){return outcome(requestId,referenceId,method,VerificationStatus.INVALID_REQUEST,code,message,null,properties.threshold(),null,null,null,List.of(code));}
 private VerificationResponse outcome(String requestId,String referenceId,String method,VerificationStatus result,String code,String message,Double similarity,Double threshold,VerificationResponse.QualityLiveness quality,VerificationResponse.Metrics metrics,VerificationResponse.ModelMetadata model,List<String> reasons){int httpStatus=result==VerificationStatus.INVALID_REQUEST?400:result==VerificationStatus.PROCESSING_ERROR?500:200;return new VerificationResponse(requestId,referenceId,method,result,code,message,httpStatus,similarity,threshold==null?properties.threshold():threshold,model==null?metadata():model,quality==null?new VerificationResponse.QualityLiveness(null,null,null):quality,metrics==null?new VerificationResponse.Metrics(0L,null,null,null):metrics,reasons==null?List.of():reasons);}
 private VerificationResponse.ModelMetadata metadata(){return new VerificationResponse.ModelMetadata(properties.modelId(),properties.modelVersion(),properties.dimension(),matcher.algorithm());}
}
